## solutions

#### depth first

```cpp
#include <unordered_map>
#include <unordered_set>
#include <vector>

bool explore(std::unordered_map<int, std::vector<int>> graph, int currentNode, std::unordered_set<int> &visited) {
  if (visited.count(currentNode) > 0) {
    return false;
  }

  visited.insert(currentNode);
  for (int neighbor : graph[currentNode]) {
    explore(graph, neighbor, visited);
  }

  return true;
}

int connectedComponentsCount(std::unordered_map<int, std::vector<int>> graph) {
  std::unordered_set<int> visited;
  int count = 0;
  for (auto pair : graph) {
    if (explore(graph, pair.first, visited)) {
      count += 1;
    }
  }
  return count;
}
```

- n = number of nodes
- e = number edges
- Time: O(e)
- Space: O(n)
